  "kind": "operation",
  "operation": {
    "operation_id": "polynomial.rational.compute.derivative",
    "title": "Differentiate a rational polynomial",
    "description": "Compute the formal derivative of one bounded polynomial in QQ[x].",
    "input_schema": {
      "$defs": {
        "CanonicalRational": {
          "additionalProperties": false,
          "description": "A reduced rational whose denominator is positive and whose zero is 0/1.",
          "examples": [
            {
              "den": "2",
              "num": "1"
            }
          ],
          "properties": {
            "num": {
              "description": "Exact numerator of the reduced rational; a native Python int and a canonical decimal string in JSON.",
              "examples": [
                "1"
              ],
              "maxLength": 32769,
              "pattern": "^(?:0|-?[1-9][0-9]{0,32767})(?![\\s\\S])",
              "title": "Num",
              "type": "string"
            },
            "den": {
              "description": "Positive exact denominator; a native Python int and a canonical decimal string in JSON. Together with num it must be reduced, and integers use den='1'.",
              "examples": [
                "2"
              ],
              "maxLength": 32768,
              "pattern": "^[1-9][0-9]{0,32767}(?![\\s\\S])",
              "title": "Den",
              "type": "string"
            }
          },
          "required": [
            "num",
            "den"
          ],
          "title": "CanonicalRational",
          "type": "object"
        },
        "RationalPolynomial": {
          "additionalProperties": false,
          "description": "One sparse polynomial together with its exact coefficient ring.",
          "properties": {
            "domain": {
              "const": "QQ",
              "default": "QQ",
              "title": "Domain",
              "type": "string"
            },
            "variables": {
              "items": {
                "pattern": "^[A-Za-z][A-Za-z0-9_]{0,31}$",
                "type": "string"
              },
              "maxItems": 8,
              "minItems": 0,
              "title": "Variables",
              "type": "array"
            },
            "polynomial": {
              "$ref": "#/$defs/SparseRationalPolynomial"
            }
          },
          "required": [
            "variables",
            "polynomial"
          ],
          "title": "RationalPolynomial",
          "type": "object"
        },
        "RationalPolynomialTerm": {
          "additionalProperties": false,
          "properties": {
            "coefficient": {
              "$ref": "#/$defs/CanonicalRational"
            },
            "exponents": {
              "items": {
                "type": "integer"
              },
              "maxItems": 8,
              "minItems": 0,
              "title": "Exponents",
              "type": "array"
            }
          },
          "required": [
            "coefficient",
            "exponents"
          ],
          "title": "RationalPolynomialTerm",
          "type": "object"
        },
        "SparseRationalPolynomial": {
          "additionalProperties": false,
          "properties": {
            "terms": {
              "default": [],
              "description": "Nonzero monomials in descending lexicographic order of their exponent tuples (highest first). For one variable, list [2] before [0].",
              "examples": [
                [
                  {
                    "coefficient": {
                      "den": "1",
                      "num": "1"
                    },
                    "exponents": [
                      2
                    ]
                  },
                  {
                    "coefficient": {
                      "den": "1",
                      "num": "-1"
                    },
                    "exponents": [
                      0
                    ]
                  }
                ]
              ],
              "items": {
                "$ref": "#/$defs/RationalPolynomialTerm"
              },
              "maxItems": 4096,
              "title": "Terms",
              "type": "array"
            }
          },
          "title": "SparseRationalPolynomial",
          "type": "object"
        }
      },
      "additionalProperties": false,
      "properties": {
        "polynomial": {
          "$ref": "#/$defs/RationalPolynomial"
        }
      },
      "required": [
        "polynomial"
