                    ]
                  },
                  {
                    "coefficient": {
                      "den": "1",
                      "num": "-1"
                    },
                    "exponents": [
                      0
                    ]
                  }
                ]
              ],
              "items": {
                "$ref": "#/$defs/RationalPolynomialTerm"
              },
              "maxItems": 4096,
              "title": "Terms",
              "type": "array"
            }
          },
          "title": "SparseRationalPolynomial",
          "type": "object"
        }
      },
      "additionalProperties": false,
      "properties": {
        "derivative": {
          "$ref": "#/$defs/RationalPolynomial"
        }
      },
      "required": [
        "derivative"
      ],
      "title": "RationalPolynomialDerivativeResult",
      "type": "object"
    },
    "read_only": true,
    "tags": [
      "polynomial",
      "rational",
      "derivative"
    ],
    "runtime_requirements": [],
    "discovery_terms": [],
    "examples": [
      {
        "name": "cubic_derivative",
        "description": "Differentiate one half x³ minus 2x.",
        "input": {
          "polynomial": {
            "domain": "QQ",
            "variables": [
              "x"
            ],
            "polynomial": {
              "terms": [
                {
                  "coefficient": {
                    "num": "1",
                    "den": "2"
                  },
                  "exponents": [
                    3
                  ]
                },
                {
                  "coefficient": {
                    "num": "-2",
                    "den": "1"
                  },
                  "exponents": [
                    1
                  ]
                }
              ]
            }
          }
        }
      }
    ]
